VALUES ('cap-lu-chunqiu-qufu-1042', 'lu-chunqiu', '曲阜', '山东省济宁市曲阜市', 116.986212, 35.581933, 'GCJ02', -1042, 1, NULL, -256, 12, NULL, -12492, -3049, 'year', 'year', 'primary', NULL, '鲁国都城曲阜。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曲阜"},{"label":"《史记·鲁周公世家》","url":"https://zh.wikisource.org/wiki/史記/卷033"}]'::jsonb)
