INSERT INTO dynasty_capitals (id, dynasty_id, historical_name, modern_name, longitude, latitude, coordinate_system, start_year, start_month, start_day, end_year, end_month, end_day, start_abs, end_abs, start_confidence, end_confidence, role, claim_track, note, links)
VALUES ('cap-jin-chunqiu-yi', 'jin-chunqiu', '翼', '山西省临汾市曲沃县、翼城县交界的曲村—天马遗址一带', 111.568992, 35.736531, 'GCJ02', -745, 1, NULL, -669, 12, NULL, -8928, -8005, 'year', 'year', 'primary', NULL, '晋国在西周时期已有早期都邑。曲村—天马遗址发现西周早期遗存与连续的晋侯墓地，是早期晋国政治中心；山西大学考古资料将其对应为早期晋都“翼”，翼的确切城址及始用年代仍有争议。前745年昭侯封成师于曲沃时，《史记》明确记翼为晋君都邑，曲沃桓叔、庄伯、武公随后与翼城公室并立。曲沃代翼后，《史记》记晋武公“始都晋国”，献公八年（前669年）“城聚都之，命曰绛”。翼另有翼城县南梁镇故城村等定位说法；地图取曲村—天马遗址代表点，不能视作已确认的翼城宫城坐标。', '[{"label":"《史记》卷三十九·晋世家：叔虞封唐、燮改号晋与昭侯时翼都","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25208.htm"},{"label":"大连博物馆《晋国雄风》：曲沃小宗与翼都大宗、上郭古城","url":"https://www.dlmodernmuseum.com/news/detail/498.html"},{"label":"山西大学考古文博学院：西周早期晋都、燮父至文侯墓葬序列与三处都邑遗址","url":"https://archaeology.sxu.edu.cn/rcpy/yxsx/199ac6ba62514d118ef56d7d17add238.htm"},{"label":"潘明娟《圣都与俗都：晋国都城体系的演变》，《中原文化研究》2021年第2期","url":"https://www.zywhyj.cn/Uploads/PdfFile/2021-03-16/60506026c2527.pdf"},{"label":"上海博物馆《晋侯墓地》：曲村—天马早期晋都及西周晋侯墓葬","url":"https://www.shanghaimuseum.net/mu/asset2/20151230150415016/"}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET dynasty_id = EXCLUDED.dynasty_id, historical_name = EXCLUDED.historical_name, modern_name = EXCLUDED.modern_name, longitude = EXCLUDED.longitude, latitude = EXCLUDED.latitude, coordinate_system = EXCLUDED.coordinate_system, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, start_confidence = EXCLUDED.start_confidence, end_confidence = EXCLUDED.end_confidence, role = EXCLUDED.role, claim_track = EXCLUDED.claim_track, note = EXCLUDED.note, links = EXCLUDED.links;
INSERT INTO dynasty_capitals (id, dynasty_id, historical_name, modern_name, longitude, latitude, coordinate_system, start_year, start_month, start_day, end_year, end_month, end_day, start_abs, end_abs, start_confidence, end_confidence, role, claim_track, note, links)
VALUES ('cap-jin-chunqiu-quwo', 'jin-chunqiu', '曲沃', '山西省运城市闻喜县桐城镇上郭村上郭城址一带', 111.240915, 35.317727, 'GCJ02', -745, 1, NULL, -678, 12, NULL, -8928, -8113, 'year', 'year', 'primary', 'quwo', '前745年晋昭侯封成师于曲沃，号桓叔，曲沃为其封邑及支系治所，当时晋君都翼。桓叔、庄伯、武公三世以曲沃为据点与翼公室争位；前739年桓叔应潘父之邀入晋，遭晋人反击后退回曲沃，双方公开对立；前678年武公代翼并受周王册命为晋侯。古曲沃据上郭城址及邱家庄墓群考古研究定位于今闻喜县，并非现代曲沃县。地图为高德上郭村的约略代表点，不是古城城墙或宫殿的精确位置；代翼后曲沃仍为宗庙所在地，不将祭祀中心自动延长为国君主都。', '[{"label":"《史记》卷三十九·晋世家：翼都、曲沃封邑与献公都绛","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25208.htm"},{"label":"大连博物馆《晋国雄风》：曲沃小宗与翼都大宗、上郭古城","url":"https://www.dlmodernmuseum.com/news/detail/498.html"},{"label":"山西大学考古文博学院：天马—曲村、上郭—邱家庄与侯马新田","url":"https://archaeology.sxu.edu.cn/rcpy/yxsx/199ac6ba62514d118ef56d7d17add238.htm"},{"label":"山东大学考古讲座：田建文《唐封晋霸西东周》，古曲沃非今曲沃","url":"https://klast.sdu.edu.cn/info/1031/1673.htm"}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET dynasty_id = EXCLUDED.dynasty_id, historical_name = EXCLUDED.historical_name, modern_name = EXCLUDED.modern_name, longitude = EXCLUDED.longitude, latitude = EXCLUDED.latitude, coordinate_system = EXCLUDED.coordinate_system, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, start_confidence = EXCLUDED.start_confidence, end_confidence = EXCLUDED.end_confidence, role = EXCLUDED.role, claim_track = EXCLUDED.claim_track, note = EXCLUDED.note, links = EXCLUDED.links;
INSERT INTO dynasty_capitals (id, dynasty_id, historical_name, modern_name, longitude, latitude, coordinate_system, start_year, start_month, start_day, end_year, end_month, end_day, start_abs, end_abs, start_confidence, end_confidence, role, claim_track, note, links)
VALUES ('cap-jin-chunqiu-jiang-669', 'jin-chunqiu', '绛（故绛）', '山西省运城市绛县一带（故绛城址有争议）', 111.568849, 35.491764, 'GCJ02', -669, 1, NULL, -585, 12, NULL, -8016, -6997, 'year', 'year', 'primary', NULL, '《史记·晋世家》记献公八年城聚、命曰绛并始都之，取前669年；《左传》庄公二十六年（前668年）另记士蒍城绛。前585年景公迁新田后称故绛。城址有绛县南城村车厢城、翼城县南梁镇故城村及曲村—天马一带等说法，翼与绛是否同址亦有争议；暂保留绛县范围约略代表点，坐标为现代行政区中心，不作为古城遗址定位。', '[{"label":"《史记》卷三十九·晋世家：翼都、曲沃封邑与献公都绛","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25208.htm"},{"label":"运城长安网：南城村车厢城与晋献公都绛的地方志记载","url":"https://www.ycpeace.gov.cn/a/wenyuan/biaolihedong/20211112/24167.html"},{"label":"潘明娟《圣都与俗都：晋国都城体系的演变》，《中原文化研究》2021年第2期","url":"https://www.zywhyj.cn/Uploads/PdfFile/2021-03-16/60506026c2527.pdf"}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET dynasty_id = EXCLUDED.dynasty_id, historical_name = EXCLUDED.historical_name, modern_name = EXCLUDED.modern_name, longitude = EXCLUDED.longitude, latitude = EXCLUDED.latitude, coordinate_system = EXCLUDED.coordinate_system, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, start_confidence = EXCLUDED.start_confidence, end_confidence = EXCLUDED.end_confidence, role = EXCLUDED.role, claim_track = EXCLUDED.claim_track, note = EXCLUDED.note, links = EXCLUDED.links;
INSERT INTO dynasty_capitals (id, dynasty_id, historical_name, modern_name, longitude, latitude, coordinate_system, start_year, start_month, start_day, end_year, end_month, end_day, start_abs, end_abs, start_confidence, end_confidence, role, claim_track, note, links)
VALUES ('cap-jin-chunqiu-xinjiang-585', 'jin-chunqiu', '新田/新绛', '山西省临汾市侯马市', 111.372002, 35.619105, 'GCJ02', -585, 1, NULL, -349, 12, NULL, -7008, -4165, 'year', 'year', 'primary', NULL, '晋景公于前585年迁都新田，亦称新绛，故址为今侯马晋国遗址。《左传·成公六年》记“夏四月丁丑”，属周历，未经可靠公历换算仅录年精度。地图保留侯马城市范围约略代表点，不表示具体宫城位置。', '[{"label":"《左传·成公六年》：晋景公迁都新田","url":"https://zh.wikisource.org/wiki/春秋左氏傳/成公"},{"label":"大连博物馆《晋国雄风》：曲沃小宗与翼都大宗、上郭古城","url":"https://www.dlmodernmuseum.com/news/detail/498.html"},{"label":"山西大学考古文博学院：天马—曲村、上郭—邱家庄与侯马新田","url":"https://archaeology.sxu.edu.cn/rcpy/yxsx/199ac6ba62514d118ef56d7d17add238.htm"}]'::jsonb)
