VALUES ('cap-qin-front-changan-351', 'qin-front', '长安', '陕西省西安市', 108.939645, 34.343207, 'GCJ02', 351, 1, NULL, 385, 6, NULL, 4212, 4625, 'year', 'month', 'primary', NULL, '前秦都城长安；《晋书·孝武帝纪》记太元十年（385）六月苻宏出降、慕容冲入长安，故该都城记录止于385年六月。该月仅表示失守所在月，无法据现有记载定到日。', '[{"label":"《晋书》卷九·孝武帝纪","url":"https://zh.wikisource.org/zh-hans/晋书/卷009"},{"label":"《西安市志》第一卷·总类：385年六月长安陷落","url":"https://dfz.shaanxi.gov.cn/zslm/fzzlk/xbsxsxz/xbsxz/xas_16198/201405/P020240923625160882829.pdf"}]'::jsonb)
