VALUES ('cap-qin-front-jinyang-385', 'qin-front', '晋阳', '山西省太原市', 112.549656, 37.870451, 'GCJ02', 385, 10, NULL, 386, 11, NULL, 4629, 4642, 'month', 'month', 'primary', NULL, '苻丕率众入据晋阳，并于此即帝位；386年留戍晋阳而自率军进屯平阳，后败亡。城市点为太原市级约略位置，不表示已定位晋阳古城遗址。苻登继立后史料所见为随战事转移的营垒与据点，暂不据此补造固定都城。', '[{"label":"《晋书》卷九·孝武帝纪","url":"https://zh.wikisource.org/zh-hans/晋书/卷009"},{"label":"《晋书》卷一百一十五·苻丕苻登载记","url":"https://www.zggdwx.com/jinshu/116.html"}]'::jsonb)
