VALUES ('cap-tang-changan', 'tang', '长安', '陕西省西安市', 108.939645, 34.343207, 'GCJ02', 618, 6, NULL, 756, 7, NULL, 7421, 9078, 'month', 'month', 'primary', NULL, '618年六月李渊受隋恭帝杨侑禅让，在长安即皇帝位建立唐朝；903年末前唐都长安。安史叛军入长安及唐军收复期间按失守至收复拆分，前段止于756年7月（月份精度）。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/长安"}]'::jsonb)
