VALUES ('cap-ming-south-guilin-1647', 'ming-south', '桂林', '广西壮族自治区桂林市', 110.179752, 25.235615, 'GCJ02', 1647, 2, 21, 1648, 3, NULL, 19765, 19778, 'month', 'approximate_month', 'primary', NULL, '绍武败后永历朝廷退守桂林。永历二年春，清军进逼后皇帝离桂林奔南宁；瞿式耜留守桂林不代表朝廷仍以桂林为驻地。按史载农历二月与公历月界换算，迁出定位约在1648年3月。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/南明"},{"label":"《永历实录》卷二：永历二年正月在桂林、二月奔南宁","url":"https://zh.wikisource.org/zh-hans/永历实录"},{"label":"中国历代朔闰表：1648年公历与农历月界","url":"https://ytliu0.github.io/ChineseCalendar/QingSouthernMingZheng_calendars.html"}]'::jsonb)
