VALUES ('cap-ming-south-zhaoqing-1648', 'ming-south', '肇庆', '广东省肇庆市', 112.465245, 23.047747, 'GCJ02', 1648, 8, NULL, 1649, 11, NULL, 19783, 19798, 'month', 'month', 'primary', NULL, '永历二年由南宁迁回肇庆，肇庆继续作为永历朝廷驻地；至永历四年清军进犯后再度西撤。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/南明"},{"label":"《永历实录》卷二：九月自南宁赴肇庆","url":"https://zh.wikisource.org/zh-hans/永历实录"}]'::jsonb)
