VALUES ('cap-mingzheng-dongdu-1661', 'mingzheng', '东都/东宁', '台湾省台南市', 120.189139, 22.989779, 'GCJ02', 1661, 4, NULL, 1683, 10, NULL, 19935, 20205, 'month', 'month', 'primary', NULL, '郑成功于1661年以台湾为东都；郑经于1664年改称东宁。两名指台南承天府同一都城，合并为一条记录；1683年十月郑克塽降清后结束。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/台湾首都"},{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/明郑"},{"label":"台南市政府：历史沿革","url":"https://origin-www.tainan.gov.tw/cp.aspx?n=13291"},{"label":"中央研究院台湾史研究所：明郑时期台湾行政疆域图","url":"https://thcts.sinica.edu.tw/themes/rb02.php"}]'::jsonb)
