VALUES ('cap-han-zhao-zuoguocheng-304', 'han-zhao', '左国城', '山西省吕梁市方山县', 111.244309, 37.895017, 'GCJ02', 304, 1, NULL, 304, 12, NULL, 3648, 3659, 'year', 'month', 'primary', NULL, '刘渊建汉初都于离石左国城。左国城具体遗址地望仍有异说；坐标采用方山县行政区约略点，不代表已确认城址。迁都年份的年桶归入迁入地，不表示公历1月1日即迁。', '[{"label":"《晋书·载记第一·刘元海》","url":"https://www.shidianguji.com/book/LS0005/chapter/LS0005_1413"},{"label":"高德地图地理编码与地点检索","url":"https://lbs.amap.com/api/webservice/guide/api/georegeo"}]'::jsonb)
