VALUES ('cap-han-zhao-liting-305', 'han-zhao', '黎亭', '山西省长治市壶关县', 113.206836, 36.115645, 'GCJ02', 305, 1, NULL, 307, 12, NULL, 3660, 3695, 'year', 'month', 'primary', NULL, '《晋书》记离石大饥后迁于黎亭；地望按今壶关县一带约略定位，未指认具体遗址。迁都年份的年桶归入迁入地。', '[{"label":"《晋书·载记第一·刘元海》","url":"https://www.shidianguji.com/book/LS0005/chapter/LS0005_1413"},{"label":"高德地图地理编码与地点检索","url":"https://lbs.amap.com/api/webservice/guide/api/georegeo"}]'::jsonb)
