VALUES ('cap-yuan-yingchang-1369', 'yuan', '应昌', '内蒙古自治区赤峰市克什克腾旗达日罕乌拉苏木应昌路故城遗址', 116.487067, 43.269985, 'GCJ02', 1369, 1, NULL, 1370, 12, NULL, 16428, 16451, 'year', 'month', 'temporary', NULL, '元顺帝北撤后驻跸应昌；1370年应昌被明军攻克，爱猷识理达腊出逃和林。年精度记录迁入、陷落所在年；高德地点为应昌路故城墓葬区附近代表点。', '[{"label":"克什克腾旗人民法院：应昌路故城遗址","url":"https://m.thepaper.cn/newsDetail_forward_27639224"},{"label":"高德地图：应昌路故城遗址","url":"https://www.amap.com/place/B0FFGSZSFZ"}]'::jsonb)
