VALUES ('cap-yuan-helin-1370', 'yuan', '和林（哈拉和林）', '蒙古国前杭爱省哈拉和林古城遗址', 102.83333, 47.23333, 'WGS84', 1370, 1, NULL, 1388, 12, NULL, 16440, 16667, 'year', 'month', 'primary', NULL, '元昭宗应昌失守后退至和林；元天元帝时期和林仍为北元的政治中心。蒙古草原汗庭具有移动性，本记录表示主要都城/政治中心，不表示汗廷全年固定驻于城内。坐标为遗址WGS84。', '[{"label":"《明太祖实录》：元昭宗、天元帝北迁及捕鱼儿海战事","url":"https://zh.wikipedia.org/wiki/%E5%A4%A9%E5%85%83_(%E5%8C%97%E5%85%83)"},{"label":"哈拉和林古城地理位置（WGS84）","url":"https://mapcarta.com/16407530"}]'::jsonb)
