VALUES ('cap-qing-hetuala-1616', 'qing', '赫图阿拉（兴京）', '辽宁省抚顺市新宾满族自治县永陵镇赫图阿拉城遗址', 124.874263, 41.705298, 'GCJ02', 1616, 1, NULL, 1619, 12, NULL, 19392, 19439, 'year', 'month', 'primary', NULL, '努尔哈赤于1616年在赫图阿拉建立后金；年精度边界按迁都年桶归入新都。坐标为高德景区点。', '[{"label":"故宫博物院：努尔哈赤年表","url":"https://www.dpm.org.cn/court/lineage/226250.html"},{"label":"高德地图：赫图阿拉城","url":"https://www.amap.com/place/B019D00ZWN"}]'::jsonb)
