VALUES ('cap-qing-liaoyang-1621', 'qing', '辽阳（东京）', '辽宁省辽阳市白塔区', 123.174347, 41.270397, 'GCJ02', 1621, 1, NULL, 1624, 12, NULL, 19452, 19499, 'year', 'month', 'primary', NULL, '后金于1621年迁都辽阳；坐标为白塔区行政区约略点，不代表东京城遗址精确位置。年精度边界按迁都年桶归入新都。', '[{"label":"故宫博物院：努尔哈赤年表","url":"https://www.dpm.org.cn/court/lineage/226250.html"},{"label":"高德地图地理编码与地点检索","url":"https://lbs.amap.com/api/webservice/guide/api/georegeo"}]'::jsonb)
