INSERT INTO dynasty_capitals (id, dynasty_id, historical_name, modern_name, longitude, latitude, coordinate_system, start_year, start_month, start_day, end_year, end_month, end_day, start_abs, end_abs, start_confidence, end_confidence, role, claim_track, note, links)
VALUES ('cap-nanzhao-tucheng-649', 'nanzhao', '图城', '云南省大理白族自治州巍山彝族回族自治县大仓镇团山村山龙山于图山城址', 100.223126, 25.348365, 'GCJ02', 649, 1, NULL, 738, 12, NULL, 7788, 8867, 'year', 'month', 'primary', NULL, '巍山县政府资料称细奴逻于649年建蒙舍诏、定都图城，738年皮逻阁迁都大理太和城。图城遗址约在今大仓镇团山村山龙山于图山顶；坐标为遗址近似点，年界只按年桶表示。个别考古资料将始建年记为650年。', '[{"label":"巍山彝族回族自治县人民政府：南诏古都","url":"https://www.dlweishan.gov.cn/wsxrmzf/c103396/pc/content/1983764863900553216/content_1983764863900553216.html"},{"label":"澎湃新闻：国家历史文化名城·云南巍山（遗址资料）","url":"https://www.thepaper.cn/newsDetail_forward_29300950"},{"label":"高德地图：山龙山于图山城址","url":"https://www.amap.com/place/B0FFKC2VLR"}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET dynasty_id = EXCLUDED.dynasty_id, historical_name = EXCLUDED.historical_name, modern_name = EXCLUDED.modern_name, longitude = EXCLUDED.longitude, latitude = EXCLUDED.latitude, coordinate_system = EXCLUDED.coordinate_system, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, start_confidence = EXCLUDED.start_confidence, end_confidence = EXCLUDED.end_confidence, role = EXCLUDED.role, claim_track = EXCLUDED.claim_track, note = EXCLUDED.note, links = EXCLUDED.links;
INSERT INTO dynasty_capitals (id, dynasty_id, historical_name, modern_name, longitude, latitude, coordinate_system, start_year, start_month, start_day, end_year, end_month, end_day, start_abs, end_abs, start_confidence, end_confidence, role, claim_track, note, links)
VALUES ('cap-jin-west-changan-304', 'jin-west', '长安', '陕西省西安市未央区汉长安城遗址', 108.849843, 34.293244, 'GCJ02', 304, 1, NULL, 306, 6, 10, 3648, 3677, 'year', 'day', 'temporary', NULL, '永安元年（304）张方挟持晋惠帝司马衷及公卿至长安，司马颙以征西府为宫；惠帝于306年6月11日还洛阳。洛阳留台仍承制行事，故此处记长安为短期朝廷实际驻地（行在），洛阳仍保留西晋京师都城记录。起点按年精度表示，史载为农历十一月，未将农历日直接换作公历月日。', '[{"label":"《晋书·惠帝纪》","url":"https://www.shidianguji.com/book/LS0005/chapter/LS0005_52"},{"label":"陕西省地方志：西安市志","url":"https://dfz.shaanxi.gov.cn/zslm/fzzlk/xbsxsxz/xbsxz/xas_16198/201405/P020240923625160882829.pdf"},{"label":"中国人民大学清史研究所：先秦至明代地理研究（引《西安历史地图集》）","url":"https://iqh.ruc.edu.cn/old/zglsdlyj/lsdl_lzjj/xqzmddlyj/490272705243483b96edc6a7eea546cd.htm"}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET dynasty_id = EXCLUDED.dynasty_id, historical_name = EXCLUDED.historical_name, modern_name = EXCLUDED.modern_name, longitude = EXCLUDED.longitude, latitude = EXCLUDED.latitude, coordinate_system = EXCLUDED.coordinate_system, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, start_confidence = EXCLUDED.start_confidence, end_confidence = EXCLUDED.end_confidence, role = EXCLUDED.role, claim_track = EXCLUDED.claim_track, note = EXCLUDED.note, links = EXCLUDED.links;
INSERT INTO dynasty_capitals (id, dynasty_id, historical_name, modern_name, longitude, latitude, coordinate_system, start_year, start_month, start_day, end_year, end_month, end_day, start_abs, end_abs, start_confidence, end_confidence, role, claim_track, note, links)
VALUES ('cap-jin-west-luoyang-306', 'jin-west', '洛阳', '河南省洛阳市', 112.453895, 34.619702, 'GCJ02', 306, 6, 11, 316, 12, NULL, 3677, 3803, 'day', 'year', 'primary', NULL, '晋惠帝于306年6月11日还洛阳后，洛阳恢复为西晋都城；本记录承接304年此前的洛阳都城阶段。', '[{"label":"《晋书·惠帝纪》：304年西迁及306年奉帝还洛阳","url":"https://www.shidianguji.com/book/LS0005/chapter/LS0005_52"},{"label":"维基百科：西晋","url":"https://zh.wikipedia.org/wiki/西晋"},{"label":"晋惠帝（归洛阳日期换算）","url":"https://zh.wikipedia.org/wiki/晋惠帝"}]'::jsonb)
