VALUES ('cap-tang-changan-757', 'tang', '长安', '陕西省西安市', 108.939645, 34.343207, 'GCJ02', 757, 11, NULL, 903, 12, NULL, 9094, 10847, 'month', 'month', 'primary', NULL, '唐军收復後恢復唐朝都城記錄；安史叛军入长安及唐军收复期間不將實際被叛軍控制的城市列作唐朝都城。757年11月為換算後的公曆月精度起點，截止仍至903年末。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/长安"}]'::jsonb)
