VALUES ('cap-tang-luoyang-757', 'tang', '洛阳', '河南省洛阳市', 112.453895, 34.619702, 'GCJ02', 757, 12, NULL, 903, 12, NULL, 9095, 10847, 'month', 'month', 'secondary', NULL, '唐军收復後恢復唐朝都城記錄；安史叛军陷洛阳及唐军收复期間不將實際被叛軍控制的城市列作唐朝都城。757年12月為換算後的公曆月精度起點，截止仍至903年末。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/洛阳"}]'::jsonb)
