INSERT INTO dynasty_capitals (id, dynasty_id, historical_name, modern_name, longitude, latitude, coordinate_system, start_year, start_month, start_day, end_year, end_month, end_day, start_abs, end_abs, start_confidence, end_confidence, role, claim_track, note, links)
VALUES ('cap-yan-anshi-luoyang-preaccession-756', 'yan-anshi', '洛阳', '河南省洛阳市', 112.453895, 34.619702, 'GCJ02', 756, 1, 18, 756, 2, 4, 9072, 9073, 'day', 'day', 'primary', NULL, '安军于天宝十四载十二月丁酉（十二日）攻取洛阳，按《资治通鉴》卷217与中国历代朔闰表换算为公历756-01-18；安禄山其后在此筹备并于至德元载正月称帝。此为称帝前的洛阳主治所阶段，终止于正式即位前一日。坐标为洛阳市区约略点。', '[{"label":"《资治通鉴》卷二百十七：天宝十四载十二月安军陷洛阳","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷217"},{"label":"中国历代朔闰表（唐、五代）：天宝十四载十二月日期换算","url":"https://ytliu0.github.io/ChineseCalendar/table_period_simp.html?period=tang5"},{"label":"《安禄山事迹》卷下：至德元载正月乙卯朔安禄山在洛阳称帝","url":"https://zh.wikisource.org/zh-hans/安祿山事跡/卷下"}]'::jsonb)
