VALUES ('cap-yan-anshi-luoyang-756', 'yan-anshi', '洛阳', '河南省洛阳市', 112.453895, 34.619702, 'GCJ02', 756, 2, 5, 757, 10, 17, 9073, 9093, 'day', 'day', 'primary', NULL, '安禄山于洛阳称帝并以此为政权中心；757年唐军收复洛阳、安庆绪北走邺城，故止于迁出前一日。坐标为洛阳市区约略点。', '[{"label":"《安禄山事迹》卷下","url":"https://zh.wikisource.org/zh-hans/安祿山事跡/卷下"},{"label":"《资治通鉴》卷219","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷219"}]'::jsonb)
