INSERT INTO dynasty_capitals (id, dynasty_id, historical_name, modern_name, longitude, latitude, coordinate_system, start_year, start_month, start_day, end_year, end_month, end_day, start_abs, end_abs, start_confidence, end_confidence, role, claim_track, note, links)
VALUES ('cap-yan-anshi-ye-757', 'yan-anshi', '邺（安成府）', '河北省邯郸市临漳县邺城遗址', 114.585514, 36.322504, 'GCJ02', 757, 10, 18, 759, 4, 6, 9093, 9107, 'day', 'day', 'primary', NULL, '安庆绪弃洛阳后退保邺郡，改邺郡为安成府；史思明杀安庆绪并接收其军后，该政权中心转至范阳。定位采用邺城遗址所在临漳县约略坐标。', '[{"label":"《资治通鉴》卷219","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷219"},{"label":"《资治通鉴》卷221","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷221"}]'::jsonb)
