INSERT INTO dynasty_capitals (id, dynasty_id, historical_name, modern_name, longitude, latitude, coordinate_system, start_year, start_month, start_day, end_year, end_month, end_day, start_abs, end_abs, start_confidence, end_confidence, role, claim_track, note, links)
VALUES ('cap-yan-anshi-fanyang-759', 'yan-anshi', '范阳/燕京', '北京市（古城址约略定位）', 116.407387, 39.904179, 'GCJ02', 759, 4, 7, 759, 9, 26, 9107, 9112, 'approximate_day', 'day', 'primary', NULL, '史思明杀安庆绪后返回范阳，并于乾元二年四月在范阳称帝、改称燕京；称帝具体公历日未能据可靠历日确定，起点以安庆绪被杀日作为接续标记并标推定。759年九月史军重新进入洛阳，主都阶段止于入城前一日。坐标是北京市区约略点，不代表已确认的唐范阳城址。', '[{"label":"《资治通鉴》卷221","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷221"},{"label":"北京日报：史思明建“都”范阳城","url":"https://peking.bjd.com.cn/content/s63a524c9e4b0450519f694a7.html"}]'::jsonb)
